steps.code:
# Get all playlists (both public and private) by paginating
all_playlists = []
for is_public in [True, False]:
    page_index = 0
    while True:
        result = apis.spotify.show_playlist_library(
            access_token=spotify_login['access_token'],
            is_public=is_public,
            page_index=page_index,
            page_limit=20
        )
        if not result:
            break
        all_playlists.extend(result)
        if len(result) < 20:
            break
        page_index += 1

print(f"Total playlists found: {len(all_playlists)}")
for p in all_playlists:
    print(f"  {p['playlist_id']}: {p['title']} (public={p['is_public']})")

# Fetch details for all unique song IDs to match against old songs
song_details = {}
for song_id in sorted(all_song_ids):
    try:
        result = apis.spotify.show_song(song_id=song_id, access_token=spotify_token)
        song_details[song_id] = result
        print(f"Song {song_id}: {result.get('title')} - {', '.join(a['name'] for a in result.get('artists', []))}")
    except Exception as e:
        print(f"Error fetching song {song_id}: {e}")

# Match old songs to song IDs by comparing title and artist names
def normalize_artists(artist_str):
    # Split by comma, strip, sort
    artists = [a.strip() for a in artist_str.split(',')]
    return sorted(artists)

# Build a lookup from old song (title, normalized_artists) to song_id
old_song_ids = set()
for title, artist_str in old_songs:
    target_artists = normalize_artists(artist_str)
    for song_id, details in song_details.items():
        song_title = details.get('title', '')
        song_artists = sorted([a['name'] for a in details.get('artists', [])])
        if song_title == title and song_artists == target_artists:
            old_song_ids.add(song_id)
            print(f"Matched: {title} by {artist_str} -> song_id {song_id}")
            break
    else:
        print(f"NO MATCH for: {title} by {artist_str}")

print(f"\nTotal matched song IDs: {len(old_song_ids)}")
print("Matched IDs:", sorted(old_song_ids))

