steps.code:
# Let's search for all archived songs to get their song IDs
archived_song_ids = []
for song in songs_to_archive:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(query=query, access_token=spotify_token)
    # Find the exact match
    match = None
    for r in results:
        if r['title'].lower() == song['title'].lower():
            # Check artist match
            for artist in r['artists']:
                if artist['name'].lower() == song['artist'].lower():
                    match = r
                    break
            if match:
                break
    if match:
        archived_song_ids.append(match['song_id'])
        print(f"Found: {song['title']} - {song['artist']} -> ID {match['song_id']}")
    else:
        print(f"NOT FOUND: {song['title']} - {song['artist']}")

print(f"\nTotal archived songs found: {len(archived_song_ids)}")

