steps.code:
# Let's search for each old song and find the exact match by title and artists.
old_song_ids = {}
for song in old_songs:
    title = song['title']
    artists = song['artists']
    # Search by title
    results = apis.spotify.search_songs(query=title, access_token=spotify_login['access_token'], page_limit=20)
    # Find exact match
    found = None
    for r in results:
        if r['title'].lower() == title.lower():
            result_artists = {a['name'].lower() for a in r['artists']}
            expected_artists = {a.lower() for a in artists}
            if result_artists == expected_artists:
                found = r
                break
    if found:
        old_song_ids[title] = found['song_id']
        print(f"Found: {title} -> song_id={found['song_id']}")
    else:
        print(f"NOT FOUND: {title}")

print(f"\nTotal found: {len(old_song_ids)}")

