# Now let's inspect each playlist to see which of the 13 target songs are present.
# First, let's define the target song IDs.
target_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}

# Get details for each playlist (IDs 513-519)
playlist_ids = [513, 514, 515, 516, 517, 518, 519]
playlist_details = {}
for pid in playlist_ids:
    result = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    playlist_details[pid] = result
    print(f"Playlist {pid}: {result['title']} - songs: {[s['id'] for s in result['songs']]}")

